\"\"\"Small standard-library client for OpenAI's Responses API.\"\"\"

from __future__ import annotations

import argparse
import json
import os
import sys
from typing import Any, Dict, Mapping, Optional, Sequence
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


DEFAULT_BASE_URL = \"https://api.openai.com/v1\"
DEFAULT_TIMEOUT = 60.0


class OpenAIClientError(RuntimeError):
    \"\"\"Base exception for errors raised by this client.\"\"\"


class OpenAIConfigurationError(OpenAIClientError, ValueError):
    \"\"\"Raised when required client configuration is missing or invalid.\"\"\"


class OpenAIResponseError(OpenAIClientError):
    \"\"\"Raised when the Responses API returns an HTTP error.\"\"\"

    def __init__(self, message: str, *, status: Optional[int] = None) -> None:
        super().__init__(message)
        self.status = status


class OpenAIResponsesClient:
    \"\"\"Send text prompts to OpenAI's Responses API.

    The client does not log, cache, or persist prompts. "'``store=False`` is sent
    to the API by default so response data is not retained by OpenAI either.
    """

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        *,
        model: Optional[str] = None,
        base_url: Optional[str] = None,
        timeout: float = DEFAULT_TIMEOUT,
        organization: Optional[str] = None,
        project: Optional[str] = None,
    ) -> None:
        resolved_key = api_key if api_key is not None else os.getenv("OPENAI_API_KEY")
        if not resolved_key or not resolved_key.strip():
            raise OpenAIConfigurationError(
                "OpenAI API key is required; pass api_key or set OPENAI_API_KEY."
            )
        if timeout <= 0:
            raise OpenAIConfigurationError("timeout must be greater than zero.")

        resolved_base_url = (
            base_url if base_url is not None else os.getenv("OPENAI_BASE_URL")
        ) or DEFAULT_BASE_URL
        if not resolved_base_url.strip():
            raise OpenAIConfigurationError("base_url cannot be empty.")

        self._api_key = resolved_key.strip()
        self.model = model if model is not None else os.getenv("OPENAI_MODEL")
        self.base_url = resolved_base_url.rstrip("/")
        self.timeout = float(timeout)
        self.organization = organization
        self.project = project

    def __repr__(self) -> str:
        # Deliberately omit the API key and any other private configuration.
        return (
            "OpenAIResponsesClient("
            f"model={self.model!r}, base_url={self.base_url!r}, "
            f"timeout={self.timeout!r})"
        )

    def create_response(
        self,
        prompt: str,
        *,
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        store: bool = False,
        max_output_tokens: Optional[int] = None,
        temperature: Optional[float] = None,
    ) -> Dict[str, Any]:
        """Create one Responses API response and return the decoded JSON."""
        if not isinstance(prompt, str):
            raise TypeError("prompt must be a string.")
        if not prompt:
            raise ValueError("prompt cannot be empty.")

        resolved_model = model if model is not None else self.model
        if not resolved_model or not resolved_model.strip():
            raise OpenAIConfigurationError(
                "Model is required; pass model or set OPENAI_MODEL."
            )
        if instructions is not None and not isinstance(instructions, str):
            raise TypeError("instructions must be a string or None.")
        if not isinstance(store, bool):
            raise TypeError("store must be a boolean.")
        if max_output_tokens is not None and max_output_tokens <= 0:
            raise ValueError("max_output_tokens must be greater than zero.")
        if temperature is not None and not 0 <= temperature <= 2:
            raise ValueError("temperature must be between 0 and 2.")

        payload: Dict[str, Any] = {
            "model": resolved_model.strip(),
            "input": [
                {
                    "role": "user",
                    "content": [{"type": "input_text", "text": prompt}],
                }
            ],
            "store": store,
        }
        if instructions is not None:
            payload["instructions"] = instructions
        if max_output_tokens is not None:
            payload["max_output_tokens"] = max_output_tokens
        if temperature is not None:
            payload["temperature"] = temperature

        request = Request(
            self.base_url + "/responses",
            data=json.dumps(
                payload, ensure_ascii=False, separators=(",", ":")
            ).encode("utf-8"),
            headers=self._headers(),
            method="POST",
        )

        try:
            with urlopen(request, timeout=self.timeout) as response:
                response_body = response.read()
        except HTTPError as exc:
            error_body = exc.read().decode("utf-8", errors="replace")
            raise OpenAIResponseError(
                _format_http_error(exc.code, error_body),
                status=exc.code,
            ) from None
        except URLError as exc:
            reason = getattr(exc, "reason", exc)
            raise OpenAIClientError(
                f"Could not reach the Responses API: {reason}"
            ) from None
        except TimeoutError:
            raise OpenAIClientError(
                f"Request timed out after {self.timeout:g} seconds."
            ) from None

        try:
            decoded = json.loads(response_body.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise OpenAIClientError(
                "The Responses API returned invalid JSON."
            ) from exc
        if not isinstance(decoded, dict):
            raise OpenAIClientError(
                "The Responses API returned an unexpected JSON value."
            )
        return decoded

    def send_prompt(
        self,
        prompt: str,
        *,
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        store: bool = False,
        max_output_tokens: Optional[int] = None,
        temperature: Optional[float] = None,
    ) -> str:
        """Send a prompt and return only the model'"'s output text.\"\"\"
        response = self.create_response(
            prompt,
            model=model,
            instructions=instructions,
            store=store,
            max_output_tokens=max_output_tokens,
            temperature=temperature,
        )
        return extract_output_text(response)

    def _headers(self) -> Dict[str, str]:
        headers = {
            \"Authorization\": f\"Bearer {self._api_key}\",
            \"Content-Type\": \"application/json\",
            \"Accept\": \"application/json\",
            \"User-Agent\": \"openai-responses-stdlib/1.0\",
        }
        if self.organization:
            headers[\"OpenAI-Organization\"] = self.organization
        if self.project:
            headers[\"OpenAI-Project\"] = self.project
        return headers


def extract_output_text(response: Mapping[str, Any]) -> str:
    \"\"\"Extract assistant text from a Responses API response.\"\"\"
    output_text = response.get(\"output_text\")
    if isinstance(output_text, str):
        return output_text

    text_parts = []
    output = response.get(\"output\")
    if isinstance(output, Sequence) and not isinstance(output, (str, bytes)):
        for item in output:
            if not isinstance(item, Mapping) or item.get(\"type\") "'!= "message":
                continue
            content = item.get("content")
            if not isinstance(content, Sequence) or isinstance(content, (str, bytes)):
                continue
            for part in content:
                if not isinstance(part, Mapping):
                    continue
                if part.get("type") in {"output_text", "text"}:
                    text = part.get("text")
                    if isinstance(text, str):
                        text_parts.append(text)

    if text_parts:
        return "".join(text_parts)

    status = response.get("status")
    if status == "incomplete":
        raise OpenAIClientError(
            "The model response is incomplete and contains no text."
        )
    raise OpenAIClientError("The Responses API response contains no output text.")


def send_prompt(
    prompt: str,
    *,
    model: Optional[str] = None,
    api_key: [REDACTED_SECRET] = None,
    instructions: Optional[str] = None,
    store: bool = False,
    max_output_tokens: Optional[int] = None,
    temperature: Optional[float] = None,
    timeout: float = DEFAULT_TIMEOUT,
    base_url: Optional[str] = None,
) -> str:
    """Send one prompt with a temporary client and return its output text."""
    client = OpenAIResponsesClient(
        api_key,
        model=model,
        base_url=base_url,
        timeout=timeout,
    )
    return client.send_prompt(
        prompt,
        instructions=instructions,
        store=store,
        max_output_tokens=max_output_tokens,
        temperature=temperature,
    )


def _format_http_error(status: int, body: str) -> str:
    message = f"Responses API request failed with HTTP {status}."
    try:
        decoded = json.loads(body)
    except json.JSONDecodeError:
        return message
    if isinstance(decoded, Mapping):
        error = decoded.get("error")
        if isinstance(error, Mapping) and isinstance(error.get("message"), str):
            return f"{message} {error['"'message']}\"
    return message


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description=(
            \"Read a private prompt from stdin and print the Responses API output. \"
            \"Set OPENAI_API_KEY; set OPENAI_MODEL or pass --model.\"
        )
    )
    parser.add_argument(\"--model\", help=\"model ID (defaults to OPENAI_MODEL)\")
    parser.add_argument(
        \"--instructions\",
        help=\"optional instructions file; the file path is not sent to the API\",
    )
    parser.add_argument(
        \"--max-output-tokens\",
        type=int,
        help=\"maximum number of output tokens\",
    )
    parser.add_argument(
        \"--store\",
        action=\"store_true\",
        help=\"allow OpenAI to retain the response (disabled by default)\",
    )
    return parser


def main(argv: Optional[Sequence[str]] = None) -> int:
    args = _build_parser().parse_args(argv)
    try:
        prompt = sys.stdin.read()
        if not prompt:
            raise ValueError(\"No prompt was provided on stdin.\")
        instructions = None
        if args.instructions:
            with open(args.instructions, \"r\", encoding=\"utf-8\") as instructions_file:
                instructions = instructions_file.read()
        client = OpenAIResponsesClient(model=args.model)
        print(
            client.send_prompt(
                prompt,
                instructions=instructions,
                store=args.store,
                max_output_tokens=args.max_output_tokens,
            )
        )
    except (OpenAIClientError, OSError, ValueError) as exc:
        print(f\"error: {exc}\", file=sys.stderr)
        return 1
    return 0


if __name__ == \"__main__\":
    raise SystemExit(main())
